-- Eldervale exploration, part 2: settings, items, explore areas, places, lore, crates, resources, shortcuts.
-- Generated by scripts/build-explore-sql.mjs from explore-data.js. Do not edit by hand.
-- APPLY AFTER db/explore-1-core.sql. Idempotent:
--  * settings ('explore' in game_settings) and catalog items are only inserted when missing (owner changes stay);
--  * explore areas are refreshed unless saved from the Underground console (updated_by set);
--  * definitions are refreshed unless saved from the Exploration console (owner_edited);
--  * explore_sync() then writes every object as a world entity (fixed ids).
begin;
set local lock_timeout='5s';
insert into eldervale_private.game_settings(key,value,updated_at) values('explore',$j${"enabled":true,"clueDrops":{"easy":{"chance":"1/128","minLevel":1,"maxLevel":30},"medium":{"chance":"1/128","minLevel":25,"maxLevel":70},"hard":{"chance":"1/256","minLevel":60,"maxLevel":999}},"steps":{"easy":[2,3],"medium":[3,5],"hard":[4,6]},"milestones":{"lore":[{"at":5,"amount":500},{"at":10,"amount":1500},{"at":15,"amount":3000},{"at":20,"amount":5000},{"at":31,"amount":12000,"title":"Loremaster"}],"place":[{"at":5,"amount":500},{"at":10,"amount":1500},{"at":20,"amount":4000},{"at":29,"amount":8000,"title":"Wayfinder"}],"clue":[{"at":1,"amount":750},{"at":10,"amount":3000,"title":"Treasure Seeker"},{"at":25,"amount":8000},{"at":50,"amount":15000,"title":"Master of Riddles"}]}}$j$::jsonb,now()) on conflict(key) do nothing;
insert into eldervale_private.realm_catalog(id,data) select r->>0,r->1 from jsonb_array_elements($j$[["item:clueEasy",{"name":"Weathered clue scroll","description":"A scrap of oilcloth, folded twice. Someone wanted you to find this — and then to keep walking.","icon":"clue","category":"Treasure","tier":"easy","kind":"clue","buy":0,"sell":0,"stackable":false,"unique":true,"shopless":true,"tradeable":false,"untradeable":true,"explore":true}],["item:clueMedium",{"name":"Sealed clue scroll","description":"Wax-sealed with a thumbprint instead of a crest. The wax is still faintly warm.","icon":"clue","category":"Treasure","tier":"medium","kind":"clue","buy":0,"sell":0,"stackable":false,"unique":true,"shopless":true,"tradeable":false,"untradeable":true,"explore":true}],["item:clueHard",{"name":"Gilt-edged clue scroll","description":"Gold leaf on the edges, ink that shifts in the light. Whoever wrote this did not expect you to finish.","icon":"clue","category":"Treasure","tier":"hard","kind":"clue","buy":0,"sell":0,"stackable":false,"unique":true,"shopless":true,"tradeable":false,"untradeable":true,"explore":true}],["item:casketEasy",{"name":"Wayfarer’s casket","description":"A small iron-bound box. It rattles encouragingly.","icon":"casket","category":"Treasure","tier":"easy","kind":"casket","buy":0,"sell":0,"stackable":false,"unique":true,"shopless":true,"tradeable":false,"untradeable":true,"explore":true}],["item:casketMedium",{"name":"Cartographer’s casket","description":"Brass corners, a compass-rose lid. Heavier than it looks.","icon":"casket","category":"Treasure","tier":"medium","kind":"casket","buy":0,"sell":0,"stackable":false,"unique":true,"shopless":true,"tradeable":false,"untradeable":true,"explore":true}],["item:casketHard",{"name":"Gilded reliquary casket","description":"Lacquered black and gold. It hums when you hold it near your ear.","icon":"casket","category":"Treasure","tier":"hard","kind":"casket","buy":0,"sell":0,"stackable":false,"unique":true,"shopless":true,"tradeable":false,"untradeable":true,"explore":true}],["item:keepsakeCompass",{"name":"Brass pathfinder’s compass","description":"The needle points not north but toward the nearest unread story.","icon":"compass","category":"Keepsakes","kind":"keepsake","rarity":"easy","buy":120,"sell":40,"stackable":false,"unique":true,"shopless":true,"tradeable":true,"untradeable":false,"explore":true}],["item:keepsakeQuill",{"name":"Gull-feather quill","description":"Cut from a Saltglass gull feather; writes a little to the left of where you aim.","icon":"quill","category":"Keepsakes","kind":"keepsake","rarity":"easy","buy":90,"sell":30,"stackable":false,"unique":true,"shopless":true,"tradeable":true,"untradeable":false,"explore":true}],["item:keepsakePebble",{"name":"Painted Moonmere pebble","description":"A smooth lake stone painted with a crescent. Fishers swap them for luck.","icon":"pebble","category":"Keepsakes","kind":"keepsake","rarity":"easy","buy":75,"sell":25,"stackable":false,"unique":true,"shopless":true,"tradeable":true,"untradeable":false,"explore":true}],["item:keepsakeLantern",{"name":"Tallow lantern charm","description":"A thumb-sized lantern on a ribbon. Its tiny wick never quite goes out.","icon":"lantern","category":"Keepsakes","kind":"keepsake","rarity":"easy","buy":135,"sell":45,"stackable":false,"unique":true,"shopless":true,"tradeable":true,"untradeable":false,"explore":true}],["item:keepsakeBottleShip",{"name":"Saltglass bottle-ship","description":"A two-master inside a green bottle. The sails are labelled with tiny, rude words.","icon":"bottle","category":"Keepsakes","kind":"keepsake","rarity":"medium","buy":360,"sell":120,"stackable":false,"unique":true,"shopless":true,"tradeable":true,"untradeable":false,"explore":true}],["item:keepsakePennant",{"name":"Moth-silk pennant","description":"A pennant spun by the grey moths of Thornveil. It moves when there is no wind.","icon":"banner","category":"Keepsakes","kind":"keepsake","rarity":"medium","buy":420,"sell":140,"stackable":false,"unique":true,"shopless":true,"tradeable":true,"untradeable":false,"explore":true}],["item:keepsakeSnowglobe",{"name":"Rimefrost snow-globe","description":"A Winterwatch souvenir. Shake it and the little watchtower is buried every time.","icon":"globe","category":"Keepsakes","kind":"keepsake","rarity":"medium","buy":330,"sell":110,"stackable":false,"unique":true,"shopless":true,"tradeable":true,"untradeable":false,"explore":true}],["item:keepsakeHourglass",{"name":"Ember-glass hourglass","description":"Sand from the Emberspire kilns. It runs upward on cold days.","icon":"hourglass","category":"Keepsakes","kind":"keepsake","rarity":"hard","buy":1140,"sell":380,"stackable":false,"unique":true,"shopless":true,"tradeable":true,"untradeable":false,"explore":true}],["item:keepsakeStarchart",{"name":"Starchart of the Quiet Lamp","description":"A sky-map with one star too many, inked in silver.","icon":"chart","category":"Keepsakes","kind":"keepsake","rarity":"hard","buy":1260,"sell":420,"stackable":false,"unique":true,"shopless":true,"tradeable":true,"untradeable":false,"explore":true}],["item:keepsakeBrooch",{"name":"Gilded cartographer’s brooch","description":"A compass-rose brooch with a tiny hinged lid. Inside: a map of the brooch.","icon":"brooch","category":"Keepsakes","kind":"keepsake","rarity":"hard","buy":1350,"sell":450,"stackable":false,"unique":true,"shopless":true,"tradeable":true,"untradeable":false,"explore":true}],["item:keepsakeCirclet",{"name":"Veilfall pearl circlet","description":"Pearls from the pool behind the falls, strung on silver wire. Rare and very much admired.","icon":"circlet","category":"Keepsakes","kind":"keepsake","rarity":"rare","buy":7500,"sell":2500,"stackable":false,"unique":true,"shopless":true,"tradeable":true,"untradeable":false,"explore":true}],["item:keepsakeWandererLantern",{"name":"The Wanderer’s Lantern","description":"An old brass lantern that throws the shadows of places you have not been yet.","icon":"lantern","category":"Keepsakes","kind":"keepsake","rarity":"rare","buy":9000,"sell":3000,"stackable":false,"unique":true,"shopless":true,"tradeable":true,"untradeable":false,"explore":true}],["item:keepsakeTidePin",{"name":"Cloak-pin of the Seventh Tide","description":"A silver pin shaped like a wave that never breaks. Smugglers would sell their boats for it.","icon":"brooch","category":"Keepsakes","kind":"keepsake","rarity":"rare","buy":8400,"sell":2800,"stackable":false,"unique":true,"shopless":true,"tradeable":true,"untradeable":false,"explore":true}]]$j$::jsonb) r on conflict(id) do nothing;
do $areas$
declare a jsonb;
begin
 for a in select value from jsonb_array_elements($j$[{"id":"veilfall_grotto","name":"Veilfall Grotto","theme":"earth","band":[1,25],"origin":{"x":1200,"z":4250},"enabled":true,"blurb":"A dry grotto behind the Veilfall, lit by crystals that drink the spray. Older than the river.","explore":true,"levels":[{"level":0,"name":"Behind the falls","rooms":[{"id":"entry","x":0,"z":0,"rx":6,"rz":5},{"id":"pool","x":20,"z":6,"rx":10,"rz":8},{"id":"gallery","x":42,"z":-4,"rx":9,"rz":7},{"id":"ledge","x":30,"z":-26,"rx":7,"rz":6}],"tunnels":[{"width":3,"points":[[0,0],[20,6]]},{"width":3,"points":[[20,6],[42,-4]]}]}],"entrances":[],"links":[],"spawns":[{"id":"bats","roster":"dusk_bat","count":3,"level":0,"room":"gallery"}],"lights":[{"level":0,"x":3,"z":-3,"kind":"crystal"},{"level":0,"x":20,"z":13,"kind":"crystal"},{"level":0,"x":14,"z":2,"kind":"fungus"},{"level":0,"x":44,"z":2,"kind":"crystal"},{"level":0,"x":30,"z":-31,"kind":"crystal"}],"seed":"explore-v1"},{"id":"thornveil_grove","name":"Thornveil Grove","theme":"earth","band":[1,30],"origin":{"x":1800,"z":4250},"enabled":true,"blurb":"A glade sealed inside a ring of thorns, where grey moths spin silk and an old spring still runs clear.","explore":true,"outdoor":{"style":"grove","ground":6126138,"groundAlt":7310405,"wall":3099170,"wallAlt":4021290},"levels":[{"level":0,"name":"The glade","rooms":[{"id":"gate","x":0,"z":0,"rx":5,"rz":5},{"id":"glade","x":24,"z":0,"rx":14,"rz":11},{"id":"spring","x":52,"z":10,"rx":8,"rz":7},{"id":"heart","x":40,"z":-26,"rx":8,"rz":7}],"tunnels":[{"width":3,"points":[[0,0],[24,0]]},{"width":3.4,"points":[[24,0],[52,10]]}]}],"entrances":[],"links":[],"spawns":[],"lights":[{"level":0,"x":52,"z":16,"kind":"fungus"},{"level":0,"x":40,"z":-30,"kind":"crystal"}],"seed":"explore-v1"},{"id":"brinehook_cove","name":"Brinehook Cove","theme":"earth","band":[10,30],"origin":{"x":2400,"z":4250},"enabled":true,"blurb":"A smugglers’ cove under the Saltglass cliffs. The tide brings boats in at night; the smugglers would rather it did not bring you.","explore":true,"levels":[{"level":0,"name":"The cove","rooms":[{"id":"mouth","x":0,"z":0,"rx":6,"rz":5},{"id":"quay","x":24,"z":4,"rx":12,"rz":8},{"id":"stash","x":48,"z":-6,"rx":9,"rz":7},{"id":"inlet","x":30,"z":30,"rx":8,"rz":6}],"tunnels":[{"width":3,"points":[[0,0],[24,4]]},{"width":3,"points":[[24,4],[48,-6]]}]}],"entrances":[],"links":[],"spawns":[{"id":"smugglers","roster":"hedge_brigand","count":3,"level":0,"room":"quay"},{"id":"lookouts","roster":"wayside_footpad","count":3,"level":0,"room":"stash"}],"lights":[{"level":0,"x":3,"z":-3,"kind":"torch"},{"level":0,"x":24,"z":11,"kind":"torch"},{"level":0,"x":48,"z":0,"kind":"brazier"},{"level":0,"x":30,"z":35,"kind":"fungus"}],"seed":"explore-v1"},{"id":"quiet_lamp_shrine","name":"Shrine of the Quiet Lamp","theme":"crypt","band":[10,25],"origin":{"x":3000,"z":4250},"enabled":true,"blurb":"A forgotten shrine under the Heartlands ruins, where the old keepers tended a lamp that was never allowed to go out.","explore":true,"levels":[{"level":0,"name":"The lamp hall","rooms":[{"id":"stair","x":0,"z":0,"rx":6,"rz":5},{"id":"nave","x":22,"z":0,"rx":10,"rz":7},{"id":"sanctum","x":46,"z":0,"rx":9,"rz":8}],"tunnels":[{"width":3,"points":[[0,0],[22,0]]},{"width":3,"points":[[22,0],[46,0]]}]}],"entrances":[],"links":[],"spawns":[{"id":"keepers","roster":"cairn_skeleton","count":3,"level":0,"room":"nave"}],"lights":[{"level":0,"x":3,"z":-3,"kind":"torch"},{"level":0,"x":22,"z":6,"kind":"brazier"},{"level":0,"x":46,"z":6,"kind":"brazier"},{"level":0,"x":52,"z":-4,"kind":"crystal"}],"seed":"explore-v1"},{"id":"gullwing_isle","name":"Gullwing Isle","theme":"earth","band":[5,30],"origin":{"x":3600,"z":4250},"enabled":true,"blurb":"A windswept island off Saltglass Bay: a broken lighthouse, a wrecked smuggler’s sloop and beaches full of things with claws.","explore":true,"outdoor":{"style":"isle","ground":13482118,"groundAlt":10464874,"wall":3108751,"wallAlt":4163238},"levels":[{"level":0,"name":"Gullwing Isle","rooms":[{"id":"landing","x":0,"z":0,"rx":7,"rz":6},{"id":"beach","x":18,"z":10,"rx":14,"rz":9},{"id":"dunes","x":38,"z":-6,"rx":13,"rz":10},{"id":"lighthouse","x":58,"z":-22,"rx":8,"rz":7},{"id":"wreck","x":52,"z":18,"rx":10,"rz":7}],"tunnels":[{"width":5,"points":[[0,0],[18,10]]},{"width":5,"points":[[18,10],[38,-6]]},{"width":4,"points":[[38,-6],[58,-22]]},{"width":4.5,"points":[[38,-6],[52,18]]}]}],"entrances":[],"links":[],"spawns":[{"id":"scuttlers","roster":"sand_scuttler","count":4,"level":0,"room":"beach"},{"id":"wights","roster":"marsh_wight","count":3,"level":0,"room":"wreck"}],"lights":[{"level":0,"x":58,"z":-26,"kind":"brazier"}],"seed":"explore-v1"},{"id":"stormcrown_plateau","name":"Stormcrown Plateau","theme":"earth","band":[25,60],"origin":{"x":4200,"z":4250},"enabled":true,"blurb":"A high plateau above the Cragmaw heights. Wolves hunt the meadow, trolls fish the tarn and the old storm-cairn still stands.","explore":true,"outdoor":{"style":"plateau","ground":7043666,"groundAlt":8358498,"wall":7105126,"wallAlt":9078656},"levels":[{"level":0,"name":"Stormcrown Plateau","rooms":[{"id":"top","x":0,"z":0,"rx":6,"rz":5},{"id":"meadow","x":22,"z":6,"rx":13,"rz":10},{"id":"tarn","x":46,"z":-8,"rx":10,"rz":8},{"id":"crown","x":60,"z":20,"rx":9,"rz":8},{"id":"scree","x":30,"z":-28,"rx":8,"rz":6}],"tunnels":[{"width":4,"points":[[0,0],[22,6]]},{"width":4,"points":[[22,6],[46,-8]]},{"width":3.6,"points":[[46,-8],[60,20]]}]}],"entrances":[],"links":[],"spawns":[{"id":"wolves","roster":"frostfang_wolf","count":4,"level":0,"room":"meadow"},{"id":"trolls","roster":"rimeback_troll","count":2,"level":0,"room":"tarn"},{"id":"ogres","roster":"cragmaw_ogre","count":2,"level":0,"room":"crown"}],"lights":[],"seed":"explore-v1"}]$j$::jsonb) loop
  insert into eldervale_private.underground_areas(id,data,enabled) values(a->>'id',a-'enabled',true)
   on conflict(id) do update set data=excluded.data,updated_at=now() where eldervale_private.underground_areas.updated_by is null and eldervale_private.underground_areas.data is distinct from excluded.data;
  perform eldervale_private.underground_sync(a->>'id');
 end loop;
end $areas$;
insert into eldervale_private.explore_defs(kind,id,data) select 'place',r->>'id',r-'id' from jsonb_array_elements($j$[{"id":"birchford","name":"Birchford","type":"town","x":-234,"z":126,"radius":30,"blurb":"The river city of House Varrow: markets, guilds and a keep full of candles."},{"id":"eldervale_castle","name":"Eldervale Castle","type":"town","x":-340,"z":-300,"radius":40,"blurb":"Seat of King Oswin, where every new adventurer starts."},{"id":"winterwatch","name":"Winterwatch","type":"town","x":217,"z":-244,"radius":28,"blurb":"The frontier town that keeps the north road open."},{"id":"emberspire","name":"Emberspire","type":"town","x":257,"z":213,"radius":28,"blurb":"Kiln-town of the south, warm in every season."},{"id":"saltglass_bay","name":"Saltglass Bay","type":"town","x":300,"z":348,"radius":26,"blurb":"Nets, gulls and a pier that has outlived three harbourmasters."},{"id":"moonmere","name":"Moonmere Lake","type":"landmark","x":-91,"z":80,"radius":30,"blurb":"A still lake where the Silverwater rests before Birchford."},{"id":"silverfin_lake","name":"Silverfin Lake","type":"landmark","x":157,"z":77,"radius":34,"blurb":"The great lake of the middle lands."},{"id":"greenwatch_pond","name":"Greenwatch Pond","type":"landmark","x":244,"z":175,"radius":20,"blurb":"A reedy pond on the Emberspire road."},{"id":"willow_fen","name":"Willow fen","type":"landmark","x":-115,"z":255,"radius":30,"blurb":"Soft ground, willow roots and things that bite at dusk."},{"id":"heron_brook","name":"Heron Brook","type":"landmark","x":150,"z":349,"radius":22,"blurb":"A clear brook with a log across it — if you trust logs."},{"id":"thornwood_edge","name":"Thornwood edge","type":"landmark","x":-330,"z":40,"radius":30,"blurb":"Where the farmland gives up and the old wood begins."},{"id":"wayfarer_camp","name":"Wayfarers’ camp","type":"landmark","x":-310,"z":-150,"radius":22,"blurb":"Tents, a cooking pot and the best stories on the Kingsroad."},{"id":"old_tams_hut","name":"Old Tam’s hut","type":"landmark","x":-335,"z":-10,"radius":18,"blurb":"A fisherman’s hut that has been “about to fall down” for forty years."},{"id":"heartlands_ruins","name":"Royal Heartlands ruins","type":"landmark","x":-120,"z":-180,"radius":30,"blurb":"Broken walls of a town nobody admits to remembering."},{"id":"cairn_hollow","name":"Cairn hollow","type":"landmark","x":-60,"z":-120,"radius":24,"blurb":"A dip in the moor ringed with stacked stones."},{"id":"frostfang_pass","name":"Frostfang pass","type":"landmark","x":60,"z":-250,"radius":30,"blurb":"The cold road north, watched by wolves."},{"id":"rimeback_crags","name":"Rimeback crags","type":"landmark","x":300,"z":-330,"radius":32,"blurb":"Ice-bitten rocks where trolls grow moss of frost."},{"id":"emberspire_scrub","name":"Emberspire scrubland","type":"landmark","x":185,"z":135,"radius":30,"blurb":"Dry heath, thornbrush and the old kiln road."},{"id":"hollowmere_cairns","name":"Hollowmere cairns","type":"landmark","x":-100,"z":-385,"radius":30,"blurb":"Cairns over a crypt that was not built to keep people out."},{"id":"bloodtusk_camp","name":"Bloodtusk war camp","type":"landmark","x":80,"z":-65,"radius":24,"blurb":"Smoke, drums and orcs who do not like visitors."},{"id":"birchroot_hollow","name":"Birchroot Hollow","type":"cave","area":"birchroot_hollow","blurb":"Roots of the birch wood above an underground stream."},{"id":"hollowmere_undercroft","name":"Hollowmere Undercroft","type":"cave","area":"hollowmere_undercroft","blurb":"The Hollow King’s court below the cairns."},{"id":"cindervault_depths","name":"Cindervault Depths","type":"cave","area":"cindervault_depths","blurb":"The fire under Cindervault that never went out."},{"id":"veilfall_grotto","name":"Veilfall Grotto","type":"hidden","area":"veilfall_grotto","blurb":"Behind the waterfall on the Westmere Run.","entrance":{"model":"waterfall_curtain","name":"The Veilfall","x":-170,"z":-300,"yaw":0,"requires":{}},"inside":{"x":2,"z":0},"exitModel":"cave_exit","hint":"The falls on the Westmere Run sound hollow behind the water."},{"id":"thornveil_grove","name":"Thornveil Grove","type":"hidden","area":"thornveil_grove","blurb":"A glade sealed inside a ring of thorns near Bramble dell.","entrance":{"model":"thorn_thicket","name":"Thornveil thicket","x":-160,"z":330,"yaw":90,"requires":{"agility":28}},"inside":{"x":2,"z":0},"exitModel":"thorn_thicket","hint":"Grey moths drift out of a thicket in Bramble dell. Something in there is not thorns."},{"id":"brinehook_cove","name":"Brinehook Cove","type":"hidden","area":"brinehook_cove","blurb":"A smugglers’ cove east of Saltglass pier.","entrance":{"model":"sea_cave","name":"Brinehook sea cave","x":350,"z":385,"yaw":180,"requires":{}},"inside":{"x":2,"z":0},"exitModel":"cave_exit","hint":"At low tide, a dark gap opens in the rocks east of the pier."},{"id":"quiet_lamp_shrine","name":"Shrine of the Quiet Lamp","type":"hidden","area":"quiet_lamp_shrine","blurb":"A forgotten shrine under the Royal Heartlands ruins.","entrance":{"model":"shrine_door","name":"Sealed shrine door","x":-112,"z":-170,"yaw":270,"requires":{"lore":"heartlands_tablet","lockedText":"The door will not move. The tablet in the ruins might explain why."}},"inside":{"x":2,"z":0},"exitModel":"stairs_up","hint":"A door with no handle stands in the Heartlands ruins."},{"id":"gullwing_isle","name":"Gullwing Isle","type":"region","area":"gullwing_isle","blurb":"An island off Saltglass Bay, reached by rowing boat from the pier.","entrance":{"model":"ferry_boat","name":"Rowing boat to Gullwing Isle","x":306,"z":376,"yaw":180,"requires":{}},"inside":{"x":2,"z":0},"exitModel":"ferry_boat","exitName":"Rowing boat to Saltglass pier","hint":"Wenna Saltglass keeps a rowing boat tied at the end of the pier."},{"id":"stormcrown_plateau","name":"Stormcrown Plateau","type":"region","area":"stormcrown_plateau","blurb":"A high plateau above the Cragmaw heights, reached by a cliff path.","entrance":{"model":"cliff_path","name":"Stormcrown cliff path","x":340,"z":-150,"yaw":0,"requires":{"agility":40}},"inside":{"x":2,"z":0},"exitModel":"cliff_path","exitName":"Cliff path down","hint":"A goat track climbs the cliffs above the Cragmaw heights."}]$j$::jsonb) r
 on conflict(kind,id) do update set data=excluded.data,updated_at=now() where not eldervale_private.explore_defs.owner_edited and eldervale_private.explore_defs.data is distinct from excluded.data;
insert into eldervale_private.explore_defs(kind,id,data) select 'lore',r->>'id',r-'id' from jsonb_array_elements($j$[{"id":"birchford_founding","name":"Founding stone of Birchford","model":"lore_tablet","region":"Birchford","x":-241,"z":121,"yaw":30,"text":"“Here the first Varrow drove a birch stake into the riverbank and said: a town, here, because the fish are stupid.” Under it, smaller, a later hand: “The fish have since learned.”"},{"id":"oswin_plinth","name":"Plinth of King Oswin the Builder","model":"lore_carving","region":"Birchford","x":-222,"z":170,"yaw":180,"text":"The plinth lists every bridge Oswin the Builder raised. The last line is chiselled and then filled in again with mortar, as if someone changed their mind about a bridge."},{"id":"lamplighter_ledger","name":"Lamplighter’s ledger","model":"lore_journal","region":"Birchford","x":-172,"z":186,"yaw":200,"text":"Night 412: Lamp on Crown Way burnt green again. Third time this month. The candle-stewards at the keep say it is my oil. My oil says it is their candles."},{"id":"candle_steward_grave","name":"Grave of a candle-steward","model":"lore_grave","region":"Birchford","x":-266,"z":92,"yaw":0,"text":"“Hesk Varrow, candle-steward. She lit four thousand candles for the house and asked for none at her grave.” Someone has left one anyway, pressed into the moss."},{"id":"heron_marker","name":"Heron Brook marker","model":"lore_carving","region":"Heron Brook","x":142,"z":343,"yaw":90,"text":"A heron is carved above a line of tally marks — one for every traveller who fell off the log. The tally is long. The heron looks smug."},{"id":"moonmere_shrine","name":"Moonmere wayside shrine","model":"lore_shrine","region":"Moonmere Lake","x":-75,"z":98,"yaw":200,"text":"Fishers leave painted pebbles here before they cast. The oldest is painted with a crescent and the words “for the one under the water, who lets us keep what we catch.”"},{"id":"silverfin_journal","name":"A wet journal","model":"lore_journal","region":"Silverfin Lake","x":157,"z":100,"yaw":0,"text":"…the Silverfin does not freeze, not even in the Long Winter my grandmother spoke of. She said the lake remembers being warm. I said lakes do not remember things. She said, “Not to you.”"},{"id":"kingsroad_milestone","name":"Kingsroad milestone","model":"lore_carving","region":"Kingsroad meadows","x":-235,"z":-185,"yaw":45,"text":"CASTLE — 4 LEAGUES. BIRCHFORD — 9 LEAGUES. Below, scratched: WINTERWATCH — TOO FAR. Below that, in a child’s hand: EMBERSPIRE — WARM."},{"id":"heartlands_tablet","name":"Tablet in the Heartlands ruins","model":"lore_tablet","region":"Royal Heartlands ruins","x":-120,"z":-180,"yaw":90,"text":"“Under the old hall the keepers tend the Quiet Lamp. The door knows the hand that has read this stone. Go softly; the lamp does not like loud feet.”"},{"id":"cairn_hollow_grave","name":"The empty cairn","model":"lore_grave","region":"Cairn hollow","x":-60,"z":-120,"yaw":0,"text":"“Here lies no one. We built it in case.” The stones are newer than the words."},{"id":"castle_gate_tablet","name":"Gate tablet of Eldervale Castle","model":"lore_tablet","region":"Eldervale Castle","x":-330,"z":-236,"yaw":180,"text":"“Every road in Eldervale begins at this gate,” the tablet says. Under it a trainee has added: “and every blister.”"},{"id":"winterwatch_frost_tablet","name":"Frost-cracked tablet","model":"lore_tablet","region":"Winterwatch","x":209,"z":-252,"yaw":0,"text":"A list of winters, each with a word: Hard. Hard. Mild. Hard. LONG. The last word is cut so deep the tablet cracked through it."},{"id":"frostfang_cairn","name":"Wolf-warden’s cairn","model":"lore_grave","region":"Frostfang pass","x":60,"z":-250,"yaw":180,"text":"“Ryn, who walked the pass forty winters and was never once bitten. The wolves came to his burial. They sat at the edge of the firelight and did not howl.”"},{"id":"pale_shepherd_carving","name":"Carving of the Pale Shepherd","model":"lore_carving","region":"Rimeback crags","x":299,"z":-328,"yaw":200,"text":"A tall figure with a crook leads a line of sheep into a cave mouth. The sheep are carved with great care. The shepherd has no face at all."},{"id":"emberspire_kiln_statue","name":"Statue of the first Emberwright","model":"lore_statue","region":"Emberspire","x":243,"z":203,"yaw":90,"text":"The Emberwright holds out a brick as if offering it to the town. The plaque reads: “She paid for the first kiln with a promise. Emberspire is still paying.”"},{"id":"emberwright_ledger","name":"Debt ledger, scorched","model":"lore_journal","region":"Emberspire scrubland","x":185,"z":135,"yaw":0,"text":"Owed: one fire, kept burning, for as long as the town stands. Paid: every year, on the coldest night. Witness: (the name is burnt away). Interest: unclear."},{"id":"cinderwing_carving","name":"Cinderwing roost stone","model":"lore_carving","region":"Cinderwing roost","x":120,"z":330,"yaw":270,"text":"Bats are carved around the stone, every one with a tiny flame for an eye. A note tucked into a crack: “Do NOT bring torches. They think it is a party.”"},{"id":"drowned_bell_tablet","name":"Tablet of the drowned bell","model":"lore_tablet","region":"Saltglass Bay","x":312,"z":356,"yaw":180,"text":"“Old Corrow stood where the bay is now. When the sea took it, the chapel bell kept ringing for a year from under the water. Then it stopped. Then, on stormy nights, it started again.”"},{"id":"old_corrow_grave","name":"Grave of Old Corrow’s last mayor","model":"lore_grave","region":"Dune stalker flats","x":200,"z":385,"yaw":0,"text":"“Mayor Ebbe Calloway, who refused to leave Old Corrow and so, technically, never did.”"},{"id":"willow_fen_journal","name":"Fen-walker’s notes","model":"lore_journal","region":"Willow fen","x":-115,"z":255,"yaw":90,"text":"Rule one: the ground is lying. Rule two: the lights are lying. Rule three: if the willow moves and there is no wind, you are lying to yourself about rule two."},{"id":"gloomfen_statue","name":"Statue with a veiled face","model":"lore_statue","region":"Gloomfen","x":-250,"z":280,"yaw":0,"text":"A woman in a veil, holding a jar. The jar is full of rainwater and very small spiders. Nobody remembers who she was; everyone in Birchford knows not to empty the jar."},{"id":"thornwood_carving","name":"Boundary stone of the Thornwood","model":"lore_carving","region":"Thornwood edge","x":-330,"z":40,"yaw":90,"text":"On one side: “FARMLAND — HOUSE VARROW.” On the other side, facing the wood, much older: “WE WERE HERE FIRST. MIND YOUR FENCES.”"},{"id":"bloodtusk_war_tablet","name":"Bloodtusk war-tablet","model":"lore_tablet","region":"Bloodtusk war camp","x":100,"z":-80,"yaw":270,"text":"Tusk-marks count the battles of the Bloodtusk clan. The last mark is not a tusk but a broken axe, and every orc who passes it spits."},{"id":"runebound_tablet","name":"Runebound warning stone","model":"lore_tablet","region":"Runebound ruins","x":-30,"z":-300,"yaw":0,"text":"Runes cover the stone. The few you can read say only: “IT IS NOT GUARDING THE RUINS. THE RUINS ARE GUARDING IT.”"},{"id":"sandscar_journal","name":"Raider’s diary","model":"lore_journal","region":"Sandscar hideout","x":70,"z":120,"yaw":180,"text":"Day 9: Captain says we rob only the rich. Day 10: Captain says everyone is rich compared to us. Day 11: robbed a goat."},{"id":"veilfall_mural","name":"Mural behind the Veilfall","model":"lore_statue","region":"Veilfall Grotto","x":44,"z":0,"yaw":270,"text":"Painted in crystal-dust: a river flowing uphill into the sky, and people walking up it carrying lanterns. Under it: “When the falls run backward, follow them.”","area":"veilfall_grotto"},{"id":"thornveil_moth_shrine","name":"Moth-silk shrine","model":"lore_shrine","region":"Thornveil Grove","x":40,"z":-26,"yaw":180,"text":"Grey moths sleep on a little stone shrine wrapped in silk. Carved underneath: “We sealed the grove so the moths could finish their weaving. They have not finished. They never will. That is the point.”","area":"thornveil_grove"},{"id":"smugglers_ledger","name":"Smugglers’ ledger","model":"lore_journal","region":"Brinehook Cove","x":46,"z":-10,"yaw":0,"text":"Brandy — 12 casks — Winterwatch (for the cold). Lamp oil — 30 jars — Birchford (for the candle-stewards, who must NOT know it is ours). Clue scrolls — 4 — “for the riddle-folk, who pay in gold and ask no questions.”","area":"brinehook_cove"},{"id":"quiet_lamp_tablet","name":"The keepers’ last tablet","model":"lore_tablet","region":"Shrine of the Quiet Lamp","x":48,"z":0,"yaw":270,"text":"“We tended the lamp for nine hundred years. It never once needed oil. On the last night we understood: it was never we who kept the lamp alight.”","area":"quiet_lamp_shrine"},{"id":"gullwing_keeper_log","name":"Lighthouse keeper’s log","model":"lore_journal","region":"Gullwing Isle","x":56,"z":-18,"yaw":0,"text":"Fog. Gulls. Fog. A sloop ran on the rocks with no lamp lit — smugglers, so I let the lamp go out too. Fog. Gulls. Someone keeps leaving riddles in the wreck. I did not write them.","area":"gullwing_isle"},{"id":"stormcrown_cairn","name":"The Stormcrown cairn","model":"lore_carving","region":"Stormcrown Plateau","x":60,"z":20,"yaw":90,"text":"Climbers add a stone and say a name. The cairn is taller than a troll and has never once been struck by the storms that strike everything else up here.","area":"stormcrown_plateau"}]$j$::jsonb) r
 on conflict(kind,id) do update set data=excluded.data,updated_at=now() where not eldervale_private.explore_defs.owner_edited and eldervale_private.explore_defs.data is distinct from excluded.data;
insert into eldervale_private.explore_defs(kind,id,data) select 'crate',r->>'id',r-'id' from jsonb_array_elements($j$[{"id":"saltglass_loft","name":"Net-loft crate","x":318,"z":330,"yaw":20},{"id":"wayfarer_supplies","name":"Wayfarers’ supply crate","x":-306,"z":-154,"yaw":70},{"id":"winterwatch_market","name":"Winterwatch market crate","x":199,"z":-235,"yaw":0},{"id":"emberspire_market","name":"Emberspire market crate","x":278,"z":224,"yaw":45},{"id":"old_tam_tackle","name":"Old Tam’s tackle crate","x":-330,"z":-15,"yaw":10},{"id":"castle_gate_stores","name":"Gatehouse stores crate","x":-345,"z":-234,"yaw":0},{"id":"cove_stash","name":"Smugglers’ stash crate","x":52,"z":-8,"yaw":30,"area":"brinehook_cove"},{"id":"isle_wreck","name":"Wreck cargo crate","x":54,"z":20,"yaw":60,"area":"gullwing_isle"}]$j$::jsonb) r
