insert into eldervale_private.explore_defs(kind,id,data) select 'resource',r->>'id',r-'id' from jsonb_array_elements($j$[{"id":"veil_gold_1","area":"veilfall_grotto","template":"rock","name":"Gold rocks","x":46,"z":-8,"resource":"goldOre"},{"id":"veil_gold_2","area":"veilfall_grotto","template":"rock","name":"Gold rocks","x":40,"z":2,"resource":"goldOre"},{"id":"grove_yew_1","area":"thornveil_grove","template":"tree","name":"Old yew","x":18,"z":6,"treeType":"yew"},{"id":"grove_yew_2","area":"thornveil_grove","template":"tree","name":"Old yew","x":30,"z":-6,"treeType":"yew"},{"id":"grove_herbs","area":"thornveil_grove","template":"herb_patch","name":"Thornveil herbs","x":52,"z":6},{"id":"shrine_altar","area":"quiet_lamp_shrine","template":"altar","name":"Altar of the Quiet Lamp","x":50,"z":0},{"id":"isle_pine_1","area":"gullwing_isle","template":"pine","name":"Wind-bent pine","x":36,"z":-12},{"id":"isle_pine_2","area":"gullwing_isle","template":"pine","name":"Wind-bent pine","x":42,"z":0},{"id":"isle_silver","area":"gullwing_isle","template":"rock","name":"Silver rocks","x":34,"z":2,"resource":"silverOre"},{"id":"isle_gold","area":"gullwing_isle","template":"rock","name":"Gold rocks","x":44,"z":-12,"resource":"goldOre"},{"id":"isle_fish_1","area":"gullwing_isle","template":"fishing_spot","name":"Gullwing shallows","x":22,"z":18,"spotType":"cage","waterHeight":0.06},{"id":"isle_fish_2","area":"gullwing_isle","template":"fishing_spot","name":"Gullwing shallows","x":8,"z":8,"spotType":"shore","waterHeight":0.06},{"id":"plateau_pine_1","area":"stormcrown_plateau","template":"pine","name":"Stormcrown pine","x":18,"z":10},{"id":"plateau_pine_2","area":"stormcrown_plateau","template":"pine","name":"Stormcrown pine","x":28,"z":2},{"id":"plateau_moon_1","area":"stormcrown_plateau","template":"rock","name":"Moonsilver rocks","x":28,"z":-30,"resource":"mithrilOre"},{"id":"plateau_moon_2","area":"stormcrown_plateau","template":"rock","name":"Moonsilver rocks","x":33,"z":-26,"resource":"mithrilOre"},{"id":"plateau_verdite","area":"stormcrown_plateau","template":"rock","name":"Verdite rocks","x":31,"z":-31,"resource":"adamantOre"},{"id":"plateau_coal_1","area":"stormcrown_plateau","template":"rock","name":"Coal rocks","x":62,"z":25,"resource":"coal"},{"id":"plateau_coal_2","area":"stormcrown_plateau","template":"rock","name":"Coal rocks","x":56,"z":24,"resource":"coal"}]$j$::jsonb) r
